import { useCallback } from "react";
import { Button, Chip, Inline } from "@kit/index.js";
import { TrackingScope, Translate, useLocalized, useSearchState, useToggleFilter, useTranslation } from "travel-platform";
import "./catalog.js";
import styles from "./FilterPanel.module.css";

function AppliedFilter({ filter }) {
    const t = useTranslation();
    const localized = useLocalized();
    const toggle = useToggleFilter();
    const label = localized(filter.label);
    const remove = useCallback(() => toggle(filter.urlId, false), [toggle, filter.urlId]);
    return <Chip selected onDismiss={remove} dismissLabel={t("filters.remove", { label })} testId="applied-filter">{label}</Chip>;
}

export default function AppliedFilters({ filters }) {
    const t = useTranslation();
    const { navigate } = useSearchState();
    if (!filters?.length)
        return null;
    return (
        <TrackingScope surface="applied-filters">
            <Inline gap={2} wrap className={styles.applied} role="region" aria-label={t("filters.applied")}>
                {filters.map((filter) => <AppliedFilter key={filter.urlId} filter={filter} />)}
                <Button variant="tertiary" size="small" onClick={() => navigate((state) => ({ ...state, filters: [], page: 0 }), "clear")}><Translate id="filters.clear" /></Button>
            </Inline>
        </TrackingScope>
    );
}
